package com.myaaptha.domain.trust;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.fasterxml.jackson.databind.*;
import com.myaaptha.domain.contacts.AddressBookService;
import com.myaaptha.domain.contacts.AddressBookController.ContactInput;
import java.util.*;import java.net.*;import java.time.*;import java.sql.Timestamp;import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.http.MediaType;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:highlights-feed-test;MODE=PostgreSQL;DB_CLOSE_DELAY=-1","myaaptha.external-feeds.initial-delay-ms=86400000"}) @AutoConfigureMockMvc
class HighlightsExternalFeedsTest {
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired JdbcTemplate db;@Autowired AddressBookService book;
 @MockitoBean PublicFeedFetcher fetcher;
 record Member(long id,String bearer){}
 String body(Object value)throws Exception{return json.writeValueAsString(value);}
 Member member()throws Exception{String name="advisor-"+UUID.randomUUID();var r=mvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON).content(body(Map.of("username",name,"password","AdvisorTest123!","phoneNumber","+1775"+String.format("%010d",Math.abs(UUID.randomUUID().getLeastSignificantBits()%10000000000L)))))).andExpect(status().isOk()).andReturn();long id=json.readTree(r.getResponse().getContentAsString()).path("id").asLong();var login=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content(body(Map.of("identifier",name,"password","AdvisorTest123!")))).andExpect(status().isOk()).andReturn();return new Member(id,"Bearer "+json.readTree(login.getResponse().getContentAsString()).path("accessToken").asText());}
 JsonNode read(Member a,String path)throws Exception{return json.readTree(mvc.perform(get(path).header("Authorization",a.bearer)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());}
 JsonNode write(Member a,String path,Object value)throws Exception{return json.readTree(mvc.perform(post(path).header("Authorization",a.bearer).contentType(MediaType.APPLICATION_JSON).content(body(value))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());}
 long postOf(Member a,String audience)throws Exception{return json.readTree(mvc.perform(multipart("/api/social/posts").header("Authorization",a.bearer).param("caption","Guidance for today").param("audience",audience)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString()).path("id").asLong();}

 void call(Member a,Member b,boolean connected,Instant at){String id=UUID.randomUUID().toString();db.update("INSERT INTO communication_calls(id,scope,target_id,creator_user_id,call_type,created_at,ended_at) VALUES(?,'DIRECT',?,?,'AUDIO',?,CURRENT_TIMESTAMP)",id,b.id,a.id,Timestamp.from(at));db.update("INSERT INTO communication_call_members(call_id,user_id,status,joined_at) VALUES(?,?,'LEFT',?)",id,a.id,Timestamp.from(at));db.update("INSERT INTO communication_call_members(call_id,user_id,status,joined_at) VALUES(?,?,?,?)",id,b.id,connected?"LEFT":"DECLINED",connected?Timestamp.from(at):null);}
 @Test void connectedCallsExcludeDeclinesOldCallsOutsidersAndPrivateRoles()throws Exception{
  var a=member();var b=member();var other=member();for(int i=0;i<3;i++)call(a,b,true,Instant.now().minusSeconds(i*60));call(a,b,false,Instant.now());call(a,b,true,Instant.now().minusSeconds(91L*86400));var page=read(a,"/api/people/highlights");assertEquals(1,page.path("items").size());assertEquals(3,page.path("items").get(0).path("connectedCalls").asInt());assertEquals(0,read(other,"/api/people/highlights").path("items").size());assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM relationships WHERE owner_user_id=?",Integer.class,a.id));
  write(a,"/api/people/highlights",Map.of("memberId",b.id,"starred",true,"hidden",true));assertEquals(0,read(a,"/api/people/highlights").path("items").size());assertEquals(1,read(a,"/api/people/highlights?view=starred").path("items").size());assertEquals(1,read(a,"/api/people/highlights?view=hidden").path("items").size());write(a,"/api/people/highlights",Map.of("memberId",b.id,"starred",true,"hidden",false));assertEquals(1,read(a,"/api/people/highlights").path("items").size());
  write(a,"/api/people/highlights/preferences",Map.of("enabled",false));assertFalse(read(a,"/api/people/highlights").path("enabled").asBoolean());assertEquals(0,read(a,"/api/people/highlights").path("items").size());assertEquals(1,read(a,"/api/people/highlights?view=starred").path("items").size());
 }
 @Test void privateContactStarsAreOwnerScopedAndHaveNoCountQuota()throws Exception{
  var a=member();var other=member();List<ContactInput> contacts=new ArrayList<>();for(int i=0;i<55;i++)contacts.add(new ContactInput("Guide "+i,List.of("+1888"+String.format("%010d",i)),List.of(),"",List.of()));book.save(a.id,contacts,"csv");var entries=book.allEntries(a.id);for(var entry:entries)write(a,"/api/people/highlights",Map.of("contactId",entry.id(),"starred",true,"hidden",false));var first=read(a,"/api/people/highlights?view=starred");assertEquals(50,first.path("items").size());assertEquals(5,read(a,"/api/people/highlights?view=starred&afterId="+first.path("nextCursor").asLong()).path("items").size());mvc.perform(post("/api/people/highlights").header("Authorization",other.bearer).contentType(MediaType.APPLICATION_JSON).content(body(Map.of("contactId",entries.getFirst().id(),"starred",true,"hidden",false)))).andExpect(status().isNotFound());
 }
 @Test void feedImportsDeduplicateAndKeepActionsAndOwnershipPrivate()throws Exception{
  var a=member();var other=member();long advisor=write(a,"/api/advisors",Map.of("name","Public guide","categories",List.of("ARTS"))).path("id").asLong();String url="https://example.org/"+UUID.randomUUID()+"/feed.xml";var item=new PublicFeedFetcher.Item("A public lesson","Short preview","https://example.org/lesson","2026-11-24T00:00:00Z");when(fetcher.fetch(url)).thenReturn(new PublicFeedFetcher.Feed("Guide feed",List.of(item)));var source=write(a,"/api/advisors/external/sources",Map.of("advisorId",advisor,"url",url,"consent",true));assertEquals(source.path("id"),write(a,"/api/advisors/external/sources",Map.of("advisorId",advisor,"url",url,"consent",true)).path("id"));var page=read(a,"/api/advisors/external?category=ARTS");assertEquals(1,page.path("items").size());assertEquals(0,read(a,"/api/advisors/external?category=LAW").path("items").size());assertEquals(0,read(other,"/api/advisors/external").path("items").size());long id=page.path("items").get(0).path("id").asLong();write(a,"/api/advisors/external/items/"+id,Map.of("saved",true,"liked",true));assertEquals(1,read(a,"/api/advisors/external?saved=true").path("items").size());mvc.perform(post("/api/advisors/external/items/"+id).header("Authorization",other.bearer).contentType(MediaType.APPLICATION_JSON).content(body(Map.of("saved",true,"liked",true)))).andExpect(status().isNotFound());
  var repost=write(a,"/api/advisors/external/items/"+id+"/repost",Map.of("confirm",true));assertEquals("A public lesson\nhttps://example.org/lesson",repost.path("caption").asText());assertEquals("PUBLIC",repost.path("audience").asText());mvc.perform(post("/api/advisors/external/sources/"+source.path("id").asLong()+"/refresh").header("Authorization",a.bearer)).andExpect(status().isTooManyRequests());mvc.perform(post("/api/advisors/external/sources/"+source.path("id").asLong()+"/delete").header("Authorization",other.bearer)).andExpect(status().isNotFound());write(a,"/api/advisors/external/sources/"+source.path("id").asLong()+"/delete",Map.of());assertEquals(0,read(a,"/api/advisors/external").path("items").size());
 }
 @Test void sourceConsentAndForeignAdvisorAreRejectedBeforeNetwork()throws Exception{
  var a=member();var other=member();long advisor=write(a,"/api/advisors",Map.of("name","Private guide","categories",List.of("LAW"))).path("id").asLong();mvc.perform(post("/api/advisors/external/sources").header("Authorization",other.bearer).contentType(MediaType.APPLICATION_JSON).content(body(Map.of("advisorId",advisor,"url","https://example.org/feed.xml","consent",true)))).andExpect(status().isNotFound());mvc.perform(post("/api/advisors/external/sources").header("Authorization",a.bearer).contentType(MediaType.APPLICATION_JSON).content(body(Map.of("advisorId",advisor,"url","https://example.org/feed.xml","consent",false)))).andExpect(status().isBadRequest());verifyNoInteractions(fetcher);
 }
 @Test void refreshFailureKeepsSavedPreviewsAndReportsOnlySafeErrors()throws Exception{
  var a=member();long advisor=write(a,"/api/advisors",Map.of("name","Guide","categories",List.of("LAW"))).path("id").asLong();String url="https://example.org/"+UUID.randomUUID()+"/feed";when(fetcher.fetch(url)).thenReturn(new PublicFeedFetcher.Feed("Legal guide",List.of(new PublicFeedFetcher.Item("Lesson","Preview","https://example.org/safe",null))));long id=write(a,"/api/advisors/external/sources",Map.of("advisorId",advisor,"url",url,"consent",true)).path("id").asLong();long item=read(a,"/api/advisors/external").path("items").get(0).path("id").asLong();write(a,"/api/advisors/external/items/"+item,Map.of("saved",true,"liked",false));db.update("UPDATE advisor_external_sources SET last_attempt=? WHERE id=?",Timestamp.from(Instant.now().minusSeconds(120)),id);when(fetcher.fetch(url)).thenThrow(new java.io.IOException("Sensitive upstream details"));mvc.perform(post("/api/advisors/external/sources/"+id+"/refresh").header("Authorization",a.bearer)).andExpect(status().isBadGateway());assertEquals(1,read(a,"/api/advisors/external?saved=true").path("items").size());write(a,"/api/advisors/external/sources/"+id+"/state",Map.of("enabled",false));assertFalse(read(a,"/api/advisors/external/sources").path("items").get(0).path("enabled").asBoolean());assertEquals(1,read(a,"/api/advisors/external?saved=true").path("items").size());String error=read(a,"/api/advisors/external/sources").path("items").get(0).path("error").asText();assertFalse(error.contains("Sensitive"));assertFalse(error.isBlank());
 }
 @Test void parserHandlesRssAtomAndRejectsEntityExpansionAndPrivateAddresses()throws Exception{
  var parser=new PublicFeedFetcher();URI base=URI.create("https://example.org/feed");var rss=parser.parse("<rss><channel><title>Guide</title><item><title>Lesson</title><description>&lt;b&gt;Practice&lt;/b&gt;</description><link>https://example.org/lesson</link></item></channel></rss>".getBytes(StandardCharsets.UTF_8),base);assertEquals("Practice",rss.items().getFirst().summary());var atom=parser.parse("<feed xmlns='http://www.w3.org/2005/Atom'><title>Video guide</title><entry><title>Lesson</title><link rel='alternate' href='https://example.org/watch'/><summary>Preview</summary></entry></feed>".getBytes(StandardCharsets.UTF_8),base);assertEquals(1,atom.items().size());assertThrows(Exception.class,()->parser.parse("<!DOCTYPE rss [<!ENTITY x SYSTEM 'file:///etc/passwd'>]><rss><channel><title>&x;</title></channel></rss>".getBytes(StandardCharsets.UTF_8),base));for(String url:List.of("http://example.org/feed","https://127.0.0.1/feed","https://169.254.169.254/","https://[::1]/","https://metadata.google.internal/","https://user:secret@example.org/feed","https://example.org:8443/feed"))assertThrows(IllegalArgumentException.class,()->PublicFeedFetcher.url(url));for(String ip:List.of("127.0.0.1","10.0.0.1","172.16.0.1","192.168.0.1","169.254.169.254","100.64.0.1","::1","fc00::1","fe80::1","2001:db8::1","2002:7f00:1::1","2001::1"))assertFalse(PublicFeedFetcher.publicAddress(InetAddress.getByName(ip)),ip);assertTrue(PublicFeedFetcher.publicAddress(InetAddress.getByName("8.8.8.8")));assertTrue(PublicFeedFetcher.publicAddress(InetAddress.getByName("192.0.66.108")));
 }
}
